import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './Thread.css';

const ThreadList = ({ forumId }) => {
    const [threads, setThreads] = useState([]);
    const [forumName, setForumName] = useState('');

    useEffect(() => {
        fetch(`/data/threadList/threadList-${forumId}.json`)
            .then(response => response.json())
            .then(data => {
                setThreads(data.threads);
                setForumName(data.forumName);
            })
            .catch(error => console.error('Error fetching thread list:', error));
    }, [forumId]);

    if (!threads || threads.length === 0) {
        return <p>No threads available</p>;
    }

    return (
        <div className="thread-list">
            <h2>{forumName}</h2>
            <ul>
                {threads.map(thread => (
                    <li key={thread.threadId} className="thread-item">
                        <div className="thread-info">
                            <div className="thread-title">
                                <Link to={`/thread/${thread.threadId}`}>{thread.title}</Link>
                            </div>
                            <div className="thread-meta">
                                <p>Started by <strong>{thread.author}</strong> on {thread.date}</p>
                            </div>
                        </div>
                        <div className="last-post-info">
                            <img src={thread.lastPost.avatar} alt={`${thread.lastPost.author}'s avatar`} className="avatar" />
                            <div className="last-post-details">
                                <p><strong>{thread.lastPost.author}</strong></p>
                                <p>{thread.lastPost.date}</p>
                                <p><em>{thread.lastPost.excerpt}</em></p>
                            </div>
                        </div>
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default ThreadList;
